function isCvBlocksObject(x) {
  return (
    x &&
    typeof x === "object" &&
    typeof x.cvVersionId === "string" &&
    Array.isArray(x.blocks)
  );
}

function tryParseJsonString(s) {
  if (typeof s !== "string") return null;
  const t = s.trim();
  if (!t) return null;
  // snabb check: måste börja med { eller [
  if (!(t.startsWith("{") || t.startsWith("["))) return null;
  try { return JSON.parse(t); } catch (e) { return null; }
}

let found = null;

// 1) Prefer explicit field if you already store it
if (isCvBlocksObject($json.normalizedModelJson)) {
  found = $json.normalizedModelJson;
}

// 2) Scan OpenAI-style output arrays
if (!found) {
  const out = $json?.output;

  if (Array.isArray(out)) {
    for (const item of out) {
      const content = item?.content;
      if (!Array.isArray(content)) continue;

      for (const c of content) {
        // Common: c.type === "output_text"
        if (isCvBlocksObject(c?.text)) { found = c.text; break; }
        if (isCvBlocksObject(c?.json)) { found = c.json; break; }

        // If model returned JSON as a string
        const parsedFromText = tryParseJsonString(c?.text);
        if (isCvBlocksObject(parsedFromText)) { found = parsedFromText; break; }

        const parsedFromJson = tryParseJsonString(c?.json);
        if (isCvBlocksObject(parsedFromJson)) { found = parsedFromJson; break; }
      }
      if (found) break;
    }
  }
}

return {
  ...$json,
  normalizedModelJson: found,
  normalizedModelError: found ? null : "No cvVersionId/blocks object found in output[].content[]",
};

const item = $input.first();
if (!item) throw new Error("No input item");

const bin = item.binary ?? {};

if (!bin.file) {
  const keys = Object.keys(bin);
  if (keys.length === 0) throw new Error("No binary found on item");
  bin.file = bin[keys[0]];
}

// Mutera item istället för att skapa nytt object literal
item.binary = { file: bin.file };

return [item];

// ===============================
// EnsureBlocksAndJoin (vNext)
// ===============================

const ENSURE_SUMMARY_ALWAYS = true; 

// ---- Label enforcement (sv flow) ----
const SV_LABELS_BY_TYPE = {
  summary: "Sammanfattning",
  profileText: "Profil",
  experience: "Erfarenheter",
  education: "Utbildning",
  certifications: "Certifieringar",
  skills: "Kompetenser",
  languages: "Språk",
  otherSections: "Övrigt",
};

function enforceSvLabel(type, incomingLabel) {
  const t = String(type || "").trim();
  const enforced = SV_LABELS_BY_TYPE[t];
  if (enforced) return enforced;
  return String(incomingLabel || "").trim();
}

function formatPeriod(startDate, endDate) {
  const s = String(startDate || "").trim();
  const e = String(endDate || "").trim();
  if (s && e) return `${s} – ${e}`;
  return s || e || "";
}


// ---- Text sanitation (defense in depth) ----
const FORBIDDEN_PREFIX_RE = /^(employer|title|startDate|endDate|degree|program|institution|order|type|label|blockId)\s*:\s*/i;

function stripLeakedKeyValueLines(text) {
  const t = String(text || "");
  if (!t.trim()) return "";
  const lines = t.split(/\r?\n/);
  const kept = [];
  for (const line of lines) {
    const l = line.trim();
    if (!l) {
      kept.push("");
      continue;
    }
    if (FORBIDDEN_PREFIX_RE.test(l)) continue;
    kept.push(line);
  }
  return kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function normLite(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/\u2013|\u2014/g, "-")
    .replace(/\s+/g, " ")
    .trim();
}

function stripFirstLineIfDuplicatesMeta(text, a, b, startDate, endDate) {
  // a/b = title+employer (experience) OR displayName+institution (education)
  let cleaned = stripLeakedKeyValueLines(text);
  if (!cleaned) return "";

  const lines = cleaned.split(/\r?\n/);
  if (!lines.length) return cleaned;

  const firstRaw = (lines[0] || "").trim().replace(/^[-•\u2022]+\s*/, "");
  const first = normLite(firstRaw);

  const period = formatPeriod(startDate, endDate);
  const needles = [a, b, period].map(normLite).filter(Boolean);

  // Om första raden innehåller någon av dessa -> sannolikt duplicering, droppa den
  const hit = needles.some((n) => n && first.includes(n));

  if (hit) {
    return lines
      .slice(1)
      .join("\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }
  return cleaned;
}

// ---- Stable ids ----
function stableHash(str) {
  let h = 0;
  const s = String(str || "");
  for (let i = 0; i < s.length; i++) {
    h = (h * 31 + s.charCodeAt(i)) >>> 0;
  }
  return h.toString(16).padStart(8, "0");
}

function makeBlockId(type, idx, identity) {
  const hash6 = stableHash(identity).slice(0, 6);
  return `${type}_${String(idx).padStart(2, "0")}_${hash6}`;
}

function norm(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/\u2013|\u2014/g, "-")
    .replace(/\s+/g, " ")
    .trim();
}

function normDate(s) {
  const t = norm(s);
  if (!t) return "";

  // yyyy-mm
  let m = t.match(/\b(\d{4})[-\/ ](\d{2})\b/);
  if (m) return `${m[1]}-${m[2]}`;

  const monthMap = {
    jan: "01",
    january: "01",
    feb: "02",
    february: "02",
    mar: "03",
    march: "03",
    apr: "04",
    april: "04",
    maj: "05",
    may: "05",
    jun: "06",
    june: "06",
    jul: "07",
    july: "07",
    aug: "08",
    august: "08",
    sep: "09",
    sept: "09",
    september: "09",
    okt: "10",
    oct: "10",
    october: "10",
    nov: "11",
    november: "11",
    dec: "12",
    december: "12",
  };

  const y = (t.match(/\b(\d{4})\b/) || [])[1];
  if (!y) return "";

  let mm = "";
  const parts = t.split(" ");
  for (let i = 0; i < parts.length; i++) {
    const tok = parts[i].replace(/[^\p{L}]/gu, "");
    if (monthMap[tok]) {
      mm = monthMap[tok];
      break;
    }
  }

  return `${y}-${mm || "00"}`;
}

function firstLine(s) {
  const t = String(s || "");
  const idx = t.indexOf("\n");
  return (idx === -1 ? t : t.slice(0, idx)).trim();
}

// För gamla modeller som skriver headern som en enda rad
function parseExperienceHeader(line) {
  const l = String(line || "").replace(/\s+/g, " ").trim();
  if (!l) return null;

  // Employer — Title (start – end)
  const m = l.match(/^(.+?)\s+[—-]\s+(.+?)\s+\((.+?)\s+[–-]\s+(.+?)\)\s*$/);
  if (!m) return null;

  const employer = norm(m[1]);
  const start = normDate(m[3]);

  const endRaw = norm(m[4]);
  const end = endRaw === "nuvarande" ? "" : normDate(m[4]);

  return { employer, start, end };
}

// Render-vänligt slutdatum (Pågående→Nuvarande)
function normalizeEndRaw(raw) {
  const t = norm(raw);
  if (!t) return "";
  if (t.includes("pågående") || t.includes("current") || t.includes("ongoing")) {
    return "Nuvarande";
  }
  return String(raw || "");
}

function normStr(v) {
  if (v == null) return "";
  return String(v).trim();
}

function asStr(v) {
  if (v == null) return "";
  return String(v);
}
function asTrimStr(v) {
  return asStr(v).trim();
}

// ---- Minimal education normalizer (safe, obvious-only) ----
function normalizeDegreeProgramObvious(degree, program) {
  const d = normStr(degree);
  const p0 = normStr(program);
  if (d || !p0) return { degree: d, program: p0 };

  const p = p0.replace(/\s+/g, " ").trim();

  // Only act if program STARTS with a clear degree token (case-insensitive)
  // Keep list small & high-precision to avoid false positives.
  const DEGREE_PREFIX_RE =
    /^(master of (arts|science|engineering)|bachelor of (arts|science|engineering)|ph\.?d\.?|doctor(ate)?|kandidatexamen|magisterexamen|masterexamen|civilingenjörsexamen|högskoleingenjörsexamen)\b/i;

  if (!DEGREE_PREFIX_RE.test(p)) return { degree: "", program: p0 };

  // Split patterns (obvious separators)
  // 1) "Master of Arts, Digital Management"
  let m = p.match(/^(.+?),(?:\s+)?(.+)$/);
  if (m) {
    return { degree: m[1].trim(), program: m[2].trim() };
  }

  // 2) "Master of Science in Computer Science"
  m = p.match(/^(.+?)\s+in\s+(.+)$/i);
  if (m) {
    return { degree: m[1].trim(), program: m[2].trim() };
  }

  // 3) Swedish: "Kandidatexamen i Systemvetenskap"
  m = p.match(/^(.+?)\s+i\s+(.+)$/i);
  if (m) {
    return { degree: m[1].trim(), program: m[2].trim() };
  }

  // If it starts with degree but we cannot safely split, move everything to degree.
  return { degree: p.trim(), program: "" };
}

// Education display name helper:
// - If degree exists and program exists: "Degree, Program" (ATS-friendly)
// - If only one exists: that one
function buildEducationDisplayName(degree, program) {
  const d = normStr(degree);
  const p = normStr(program);
  if (d && p) return `${d}, ${p}`;
  return d || p || "";
}

// ===============================
// 1) Hämta model output blocks
// Prefer sanitizedModelJson -> normalizedModelJson
// ===============================
const modelObj =
  $json.sanitizedModelJson && typeof $json.sanitizedModelJson === "object"
    ? $json.sanitizedModelJson
    : $json.normalizedModelJson && typeof $json.normalizedModelJson === "object"
      ? $json.normalizedModelJson
      : null;

const blocksIn = Array.isArray(modelObj?.blocks) ? modelObj.blocks : [];

if (!blocksIn.length) {
  return {
    json: {
      ok: false,
      contractError: {
        code: "NO_BLOCKS_FROM_MODEL",
        message: String(
          $json.sanitizedModelError ||
          $json.normalizedModelError ||
          "No blocks from model"
        ),
      },
      blocksSchemaVersion: "1.0",

      blocks: [],
      rewrittenCv: "",
      rewrittenCvLegacy: "",

      cvVersionId:
        String($json.cvVersionId || modelObj?.cvVersionId || "").trim() ||
        `cv_${Date.now()}`,
      cvTitle: String($json.cvTitle || "").trim(),
      summaryOfChanges: String($json.summaryOfChanges || "").trim(),
    },
  };
}








// ===============================
// 2) parsedCvJson (sanningen)
// ===============================
let parsedObj = null;
const parsedRaw = $json.parsedCvJson;

if (typeof parsedRaw === "string") {
  try {
    parsedObj = JSON.parse(parsedRaw);
  } catch (e) {
    parsedObj = null;
  }
} else if (parsedRaw && typeof parsedRaw === "object") {
  parsedObj = parsedRaw;
}

const parsedExperiences = Array.isArray(parsedObj?.experiences) ? parsedObj.experiences : [];
const parsedEducation = Array.isArray(parsedObj?.education) ? parsedObj.education : [];

const personalInfo = parsedObj?.personalInfo || {};

// cvTitle: prefer model -> personalInfo -> first experience title
const modelTitle = String(modelObj?.cvTitle || "").trim();
const derivedTitle =
  (personalInfo.currentTitle && String(personalInfo.currentTitle).trim()) ||
  (parsedExperiences[0]?.title ? String(parsedExperiences[0].title).trim() : "");
const cvTitle = modelTitle || derivedTitle || "";

// ===============================
// 3) Deterministiska ID-maps från parsedCvJson
// ===============================
const expMap = parsedExperiences.map((e, i) => {
  const employer = norm(e?.employer);
  const start = normDate(e?.startDateRaw);
  const end = normDate(e?.endDateRaw);
  const identity = `exp|${i}|${employer}|${start}|${end}`;
  return { idx: i, identity, blockId: makeBlockId("experience", i, identity) };
});

const eduMap = parsedEducation.map((ed, i) => {
  const inst = norm(ed?.institution);

  // IMPORTANT: normalize obvious degree/program mistakes BEFORE identity to keep IDs stable
  let degree = normStr(ed?.degree);
  let program = normStr(ed?.program);
  const fixed = normalizeDegreeProgramObvious(degree, program);
  degree = norm(fixed.degree);
  program = norm(fixed.program);

  const start = normDate(ed?.startDateRaw);
  const end = normDate(ed?.endDateRaw);

  // IMPORTANT: include degree/program in identity so different educations at same institution don't collide
  const identity = `edu|${i}|${inst}|${degree}|${program}|${start}|${end}`;
  return { idx: i, identity, blockId: makeBlockId("education", i, identity) };
});

const summaryId = makeBlockId("summary", 0, "summary|canonical");
const skillsId = makeBlockId("skills", 0, "skills|canonical");
const languagesId = makeBlockId("languages", 0, "languages|canonical");
const certsId = makeBlockId("certifications", 0, "certifications|canonical");

// ===============================
// 4) Normalisera model blocks, sortera på order
// ===============================
const pre = blocksIn
  .map((b) => {
    const rawType = String(b?.type || "block").trim();
    const type = rawType === "profileText" || rawType === "profile"  ? "summary" : rawType;
    const label = String(b?.label || "").trim();
    const order = Number.isFinite(Number(b?.order)) ?   Number(b.order) : 9999;

    // SANERA TEXT HÄR (så tidigt som möjligt)
    const text = stripLeakedKeyValueLines(b?.text);

    return { type, label, order, text, _rawType: rawType, _raw: b };
  })
  .sort((a, b) => a.order - b.order);

// ===============================
// 5) Tilldela stabila blockId + injicera employer/title/dates etc
// ===============================
const usedExp = new Set();
const usedEdu = new Set();
const typeCounts = Object.create(null);
let otherIdx = 0;

let normalizedBlocks = pre.map((b) => {
  typeCounts[b.type] = (typeCounts[b.type] || 0) + 1;
  const typeIdx = typeCounts[b.type] - 1;

  // Canonical summary
  if (b.type === "summary") {
    return {
      blockId: summaryId,
      type: "summary",
      label: enforceSvLabel("summary", b.label),
      order: b.order,
      text: asTrimStr(b.text),
    };
  }

  // EXPERIENCE: koppla mot parsedCvJson + injicera employer/title/dates
  if (b.type === "experience") {
    let blockId = "";
    let expIdx = -1;

    const header = parseExperienceHeader(b.label) || parseExperienceHeader(firstLine(b.text));

    if (header) {
      for (let i = 0; i < parsedExperiences.length; i++) {
        const e = parsedExperiences[i];
        const employerN = norm(e?.employer);
