function normDate(s) {
  const t = norm(s);
  if (!t) return "";

  // yyyy-mm
  let m = t.match(/\b(\d{4})[-\/ ](\d{2})\b/);
  if (m) return `${m[1]}-${m[2]}`;

  const monthMap = {
    jan: "01",
    january: "01",
    feb: "02",
    february: "02",
    mar: "03",
    march: "03",
    apr: "04",
    april: "04",
    maj: "05", // Swedish (kept for robust parsing)
    may: "05",
    jun: "06",
    june: "06",
    jul: "07",
    july: "07",
    aug: "08",
    august: "08",
    sep: "09",
    sept: "09",
    september: "09",
    okt: "10", // Swedish (kept for robust parsing)
    oct: "10",
    october: "10",
    nov: "11",
    november: "11",
    dec: "12",
    december: "12",
  };

  const y = (t.match(/\b(\d{4})\b/) || [])[1];
  if (!y) return "";

  let mm = "";
  const parts = t.split(" ");
  for (let i = 0; i < parts.length; i++) {
    const tok = parts[i].replace(/[^\p{L}]/gu, "");
    if (monthMap[tok]) {
      mm = monthMap[tok];
      break;
    }
  }

  return `${y}-${mm || "00"}`;
}

