  // 1) "Master of Arts, Digital Management"
  let m = p.match(/^(.+?),(?:\s+)?(.+)$/);
  if (m) {
    return { degree: m[1].trim(), program: m[2].trim() };
  }

  // 2) "Master of Science in Computer Science"
  m = p.match(/^(.+?)\s+in\s+(.+)$/i);
  if (m) {
    return { degree: m[1].trim(), program: m[2].trim() };
  }

  // 3) Swedish format: "Kandidatexamen i Systemvetenskap"
  // (kept for robust parsing; output labels/text remain English in this flow)
  m = p.match(/^(.+?)\s+i\s+(.+)$/i);
  if (m) {
    return { degree: m[1].trim(), program: m[2].trim() };
  }

  // If it starts with a degree but we cannot safely split, move everything to degree.
  return { degree: p.trim(), program: "" };
