function toStr(x) {
  return (x == null) ? "" : String(x);
}

function trimOrEmpty(x) {
  return toStr(x).trim();
}

// ADD program here
const FORBIDDEN_PREFIX_RE = /^(employer|title|startDate|endDate|degree|program|institution|order|type|label|blockId)\s*:\s*/i;

function stripLeakedKeyValueLines(text) {
  const t = toStr(text);
  if (!t.trim()) return "";
  const lines = t.split(/\r?\n/);
  const kept = [];
  for (const line of lines) {
    const l = line.trim();
    if (!l) { kept.push(""); continue; }
    if (FORBIDDEN_PREFIX_RE.test(l)) continue;
    kept.push(line);
  }
  return kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function norm(s) {
  return trimOrEmpty(s).toLowerCase().replace(/\s+/g, " ");
}

function stripEducationFirstLineIfDuplicate(text, degree, institution, startDate, endDate) {
  let cleaned = stripLeakedKeyValueLines(text);
  if (!cleaned) return "";

  const lines = cleaned.split(/\r?\n/);
  if (!lines.length) return cleaned;

  const firstRaw = lines[0].trim().replace(/^[-•\u2022]+\s*/, "");
  const first = norm(firstRaw);

  const period = trimOrEmpty(`${startDate}${(startDate || endDate) ? " – " : ""}${endDate}`);

  const needles = [ norm(degree), norm(institution), norm(period) ].filter(Boolean);
  const hit = needles.some(n => n && first.includes(n));

  if (hit) {
    return lines.slice(1).join("\n").replace(/\n{3,}/g, "\n\n").trim();
  }
  return cleaned;
}

