  const endDate = trimOrEmpty(block.endDate);
  if (endDate) return endDate;

  const text = norm(block.text);
  const hints = ["nuvarande", "present", "pågående", "ongoing"];
  if (hints.some(h => text.includes(h))) return "Nuvarande";

  return "";
